def transform(grid):
    """Fill the interiors of downward-pointing outlined triangles with 2."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    h, w = len(grid), len(grid[0])
    # Each top-row marker is the apex of a downward triangle. Its two
    # diagonal sides move one column outward per row; fill strictly between.
    for c0, color in enumerate(grid[0]):
        if color == 0:
            continue
        for r in range(1, h):
            left, right = c0 - r, c0 + r
            for c in range(max(0, left + 1), min(w, right)):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out

